function setupSiteWarning(){
 const name=$('#label'),row=document.createElement('div');row.className='place-name-row';name.before(row);row.append(name);
 const button=document.createElement('button');button.id='site-warning';button.hidden=true;button.type='button';button.setAttribute('popovertarget','site-warning-details');button.setAttribute('aria-expanded','false');button.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M10.3 3.8 2.2 18a2 2 0 0 0 1.7 3h16.2a2 2 0 0 0 1.7-3L13.7 3.8a2 2 0 0 0-3.4 0Z"/><path d="M12 9v4m0 4h.01"/></svg>';row.append(button);
 const details=document.createElement('div');details.id='site-warning-details';details.setAttribute('popover','auto');details.setAttribute('role','status');document.body.append(details);
 details.addEventListener('toggle',e=>button.setAttribute('aria-expanded',String(e.newState==='open')));
}
function updateSiteWarning(){
 const button=$('#site-warning'),details=$('#site-warning-details');if(!button)return;
 const count=active?.assembly?.placementIssues?.length||0;button.hidden=!count;
 if(!count){if(details.matches(':popover-open'))details.hidePopover();return;}
 const label=count+' site '+(count===1?'issue':'issues');button.title=label;button.setAttribute('aria-label',label+'. Show details');
 const text=label+'. Some activities may be blocked by terrain or space.';if(details.textContent!==text)details.textContent=text;
}

